public int findMinimumWeightWalk(int N, int[][] edges) {
    // Initialize graph representation
    int[][] graph = new int[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            graph[i][j] = Integer.MAX_VALUE;
        }
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        int w = edge[2];
        graph[u][v] = Math.min(graph[u][v], w);
    }

    // Check for existence of a walk that visits each vertex at least once
    boolean[] visited = new boolean[N];
    dfs(0, visited, graph);

    for (boolean v : visited) {
        if (!v) return -1; // If any vertex is not visited, return -1
    }

    // Calculate minimum total weight of the walk
    int minWeight = 0;
    for (int i = 0; i < N; i++) {
        int minEdge = Integer.MAX_VALUE;
        for (int j = 0; j < N; j++) {
            if (graph[i][j] < minEdge) {
                minEdge = graph[i][j];
            }
        }
        if (minEdge == Integer.MAX_VALUE) return -1; // If no outgoing edge, return -1
        minWeight += minEdge;
    }

    return minWeight;
}

private void dfs(int node, boolean[] visited, int[][] graph) {
    visited[node] = true;
    for (int i = 0; i < graph.length; i++) {
        if (graph[node][i] != Integer.MAX_VALUE && !visited[i]) {
            dfs(i, visited, graph);
        }
    }
}
